namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class DistrictFinish {
static DistrictFinish(){EditorApplication.update+=Poll;}
static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isUpdating||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("Temp/Mok-district-finish"))return;File.Delete("Temp/Mok-district-finish");try{Run();}catch(Exception e){File.WriteAllText("Temp/Mok-district-finish.txt",e.ToString());}}
static void Box(Transform p,string n,Vector3 pos,Vector3 size,Material m){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=n;g.transform.SetParent(p);g.transform.position=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=m;UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());g.isStatic=true;}
static void Run(){var old=SceneManager.GetActiveScene();for(int i=0;i<SceneManager.sceneCount;i++)EditorSceneManager.SaveScene(SceneManager.GetSceneAt(i),"Temp/Before-district-finish-"+DateTime.Now.ToString("HHmmss")+"-"+i+".unity",true);var s=SceneManager.GetSceneByPath("Assets/Scenes/JJinCity.unity");bool opened=!s.isLoaded;if(opened)s=EditorSceneManager.OpenScene("Assets/Scenes/JJinCity.unity",OpenSceneMode.Additive);SceneManager.SetActiveScene(s);EditorSceneManager.SaveScene(s,"Temp/JJinCity-before-district-finish.unity",true);
var w=s.GetRootGameObjects().First(g=>g.name=="Mok West Quarter");
if(w.transform.Find("Quarter details")==null){var details=new GameObject("Quarter details").transform;details.SetParent(w.transform);var metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/Districts/Dark steel.mat");var yellow=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/Districts/Faded yellow.mat");var roof=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/Districts/Weathered roof.mat");var plaster=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/Districts/Old plaster.mat");
for(int i=0;i<7;i++){float x=-218-i*19;Box(details,"Overhead utility wire",new Vector3(x,5,-5),new Vector3(.035f,.035f,24),metal);foreach(int side in new[]{-1,1}){Box(details,"Market display table",new Vector3(x, .65f,-5+side*5.8f),new Vector3(3,.2f,1.1f),roof);foreach(float dx in new[]{-1.2f,1.2f})Box(details,"Display table legs",new Vector3(x+dx,.3f,-5+side*5.8f),new Vector3(.1f,.6f,.8f),metal);for(int k=0;k<3;k++)Box(details,"Market produce crate",new Vector3(x-1+k,.95f,-5+side*5.8f),new Vector3(.7f,.4f,.7f),k%2==0?yellow:plaster);
var sign=new GameObject("Market sign");sign.transform.SetParent(details);sign.transform.position=new Vector3(x,2.65f,-5+side*6.85f);sign.transform.rotation=Quaternion.Euler(0,side<0?180:0,0);var tm=sign.AddComponent<TextMesh>();tm.font=AssetDatabase.LoadAssetAtPath<Font>("Assets/Fonts/BMJUA_ttf.ttf");tm.fontSize=48;tm.characterSize=.055f;tm.anchor=TextAnchor.MiddleCenter;tm.text=new[]{"골목 식료품","서안 수선","중고 잡화","우리 상회","골목 세탁","생활 용품","서안 시장"}[i];tm.color=new Color(.9f,.77f,.5f);sign.GetComponent<MeshRenderer>().sharedMaterial=tm.font.material;}}
// 높은 지붕 사이 빨랫줄은 충돌 없이 골목의 생활감을 표현한다.
for(int i=0;i<7;i++){float x=-218-i*19;foreach(float z in new[]{-35f,45f}){Box(details,"Laundry line",new Vector3(x,4,z),new Vector3(5,.025f,.025f),metal);for(int k=0;k<4;k++)Box(details,"Hanging laundry",new Vector3(x-1.8f+k*1.1f,3.5f,z),new Vector3(.7f,.9f,.035f),k%2==0?plaster:roof);}}
}
foreach(var tm in w.GetComponentsInChildren<TextMesh>())if(tm.text.StartsWith("도보 전용")){tm.transform.position=new Vector3(-194.74f,2.95f,-5);tm.characterSize=.045f;}
var east=s.GetRootGameObjects().First(g=>g.name=="Mok East City");
if(east.transform.Find("East frontage map")==null){
var verts=new List<Vector3>();var tris=new List<int>();
foreach(var t in east.transform.Find("Street frontage").GetComponentsInChildren<Transform>().Where(t=>t.name.StartsWith("East shop frontage"))){var rr=t.GetComponentsInChildren<Renderer>();var b=rr[0].bounds;foreach(var r in rr)b.Encapsulate(r.bounds);t.RotateAround(b.center,Vector3.up,180);PrefabUtility.RecordPrefabInstancePropertyModifications(t);int n=verts.Count;verts.AddRange(new[]{new Vector3(b.min.x,.21f,b.min.z),new Vector3(b.min.x,.21f,b.max.z),new Vector3(b.max.x,.21f,b.max.z),new Vector3(b.max.x,.21f,b.min.z)});tris.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}
var mesh=new Mesh{name="East shop map"};mesh.SetVertices(verts);mesh.SetTriangles(tris,0);mesh.RecalculateBounds();AssetDatabase.CreateAsset(mesh,"Assets/Scripts/Mok/Art/Districts/East frontage map.asset");var map=new GameObject("East frontage map");map.transform.SetParent(east.transform);map.layer=20;map.AddComponent<MeshFilter>().sharedMesh=mesh;map.AddComponent<MeshRenderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Art/NavigationMap/Buildings.mat");}
if(east.transform.Find("Bridge smooth collision")==null){
foreach(var c in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Collider>(true))){if(!c.name.StartsWith("SM_Env_Road_")||!c.enabled)continue;var b=c.bounds;bool bridge=(b.center.x>140&&b.center.x<195)||(b.center.x< -100&&b.center.x> -155);if(bridge&&b.center.z> -10&&b.center.z<0){c.enabled=false;if(PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);}}
foreach(var region in new[]{new Vector3(167.5f,55,0),new Vector3(-127.5f,55,0)}){var g=new GameObject("Bridge smooth collision");g.transform.SetParent(east.transform);g.transform.position=new Vector3(region.x,-.08f,-5);g.AddComponent<BoxCollider>().size=new Vector3(region.y,.16f,10);g.isStatic=true;}
}
foreach(var c in east.GetComponentsInChildren<Collider>(true))if(!c.enabled&&PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);
// 새로 생성된 콜라이더는 bounds 동기화 시점에 의존하지 않고 변환 행렬로 굽는다.
var sources=new List<NavMeshBuildSource>();foreach(var c in w.GetComponentsInChildren<BoxCollider>()){if(!c.enabled||c.name=="Quarter foundation"||c.name=="Motorcycle entry barrier")continue;int area=c.name=="Quarter walkable floor"?NavMesh.GetAreaFromName("SideWalk"):c.name=="Bridge parking approach"?NavMesh.GetAreaFromName("Road"):1;sources.Add(new NavMeshBuildSource{shape=NavMeshBuildSourceShape.Box,transform=c.transform.localToWorldMatrix*Matrix4x4.Translate(c.center),size=c.size,area=area});}
var data=NavMeshBuilder.BuildNavMeshData(NavMesh.GetSettingsByIndex(0),sources,new Bounds(new Vector3(-260,20,-5),new Vector3(214,50,164)),Vector3.zero,Quaternion.identity);var asset=AssetDatabase.LoadAssetAtPath<NavMeshData>("Assets/Scripts/Mok/Art/Districts/West quarter navigation.asset");EditorUtility.CopySerialized(data,asset);UnityEngine.Object.DestroyImmediate(data);EditorUtility.SetDirty(asset);var surface=w.GetComponentInChildren<NavMeshSurface>();surface.RemoveData();surface.navMeshData=asset;surface.AddData();var link=w.GetComponentInChildren<NavMeshLink>();link.startPoint=new Vector3(-150,.1f,-5);link.UpdateLink();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);SceneManager.SetActiveScene(old);if(opened)EditorSceneManager.CloseScene(s,true);File.WriteAllText("Temp/Mok-district-finish.txt","Saved; navigation sources="+sources.Count);}
}}
